package setup

import (
	"strconv"

	"github.com/KogenAI/kogen-loop/sys"
)

// initInvalidMaxLines is how many problems the refusal lists before it counts the rest.
const initInvalidMaxLines = 5

// initInvalidError is the refusal when the last answer of the setup conversation was not a
// valid configuration. problems are the reasons Validate gave for that last answer; none means
// the answer did not call submit_configuration.
func initInvalidError(problems []string) *sys.Error {
	e := sys.Fail("provider", "init_invalid", "the model did not return a valid configuration; nothing was written", 4)
	if len(problems) == 0 {
		e.Lines = []string{"the last answer did not call submit_configuration"}
		return e
	}
	shown := problems
	if len(shown) > initInvalidMaxLines {
		shown = shown[:initInvalidMaxLines]
	}
	e.Lines = append([]string(nil), shown...)
	if rest := len(problems) - len(shown); rest > 0 {
		noun := "problems"
		if rest == 1 {
			noun = "problem"
		}
		e.Lines = append(e.Lines, "and "+strconv.Itoa(rest)+" more "+noun)
	}
	return e
}

